import{_ as r,l as t,o,c as l,v as e,p,x as n,d as i,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"Thompson 构造","description":"","frontmatter":{"title":"Thompson 构造","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/thompson-nfa.md","filePath":"cs/thompson-nfa.md","lastUpdated":1789023840000}'),d={name:"cs/thompson-nfa.md"};function c(A,a,T,_,f,u){const s=t("Mermaid");return o(),l("div",null,[a[1]||(a[1]=e('<h1 id="thompson-构造" tabindex="-1">Thompson 构造 <a class="header-anchor" href="#thompson-构造" aria-label="Permalink to &quot;Thompson 构造&quot;">​</a></h1><div class="epigraph"><p>正则的并、连接与星号各对应一小块带 $\\varepsilon$ 边的 NFA；结构归纳拼出整式，状态数与式子大小线性。</p><footer>—— 据 Thompson, Regular Expression Search Algorithm, 1968；龙书第 3 章整理</footer></div><p>上一课<a href="/cs/nfa-dfa">NFA 与 DFA</a>给出子集构造，但正则表达式还没有自动机。词法课把「正则 → NFA」写成箭头。本课不重做确定化。缺口是 Thompson：每个子式一块 NFA，一个入口、一个出口，\\(\\varepsilon\\) 连接三算子。拼完再确定化，词法器才真正落地。后课嵌套括号超出正则，换成 CFG。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正则式 \\(\\varepsilon\\)、\\(a\\)、\\(E|F\\)、\\(EF\\)、\\(E^*\\) 的语法树要对成机器。Thompson：原子是两态一条标号边（或 \\(\\varepsilon\\)）。并为两入口 \\(\\varepsilon\\) 分叉、两出口 \\(\\varepsilon\\) 汇合；连接把前一块出口 \\(\\varepsilon\\) 接到后一块入口；星号是绕回加可跳过的 \\(\\varepsilon\\)。每块恰好一入一出，避免乱接。缺口是这份归纳，不是再定义正则语言。</p><p>状态数 \\(O(|E|)\\)，边数同样。确定化仍可能指数，但 NFA 本身瘦，适合先构造再子集。McNaughton–Yamada / Glushkov 无 \\(\\varepsilon\\) 的另一构造，本课点名，主干用 Thompson。</p><h3 id="边是拼装胶水" tabindex="-1">\\(\\varepsilon\\) 边是拼装胶水 <a class="header-anchor" href="#边是拼装胶水" aria-label="Permalink to &quot;$\\varepsilon$ 边是拼装胶水&quot;">​</a></h3><p>运行期 DFA 不再看见 \\(\\varepsilon\\)：子集构造时闭包掉。不要在 DFA 上保留 \\(\\varepsilon\\)。也不要把 Thompson 的出口当接受态之外再挂长链——每块出口即该子式的接受。</p><p><span class="marginnote">Thompson 1968，CACM。龙书 3.7 节图示四块。Hopcroft–Ullman 把正则与 NFA 互译当定理；本课要编译器用的那一方向。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>递归下降读正则式（或已有的正则 AST），按算子 new 状态、加 \\(\\varepsilon\\)。全体并成词法大 NFA：新起点 \\(\\varepsilon\\) 连到各种别的 Thompson 机，各出口标种别。再子集构造，冲突用最长匹配与规则序——词法课已有，本课不重写。</p>',11)),(o(),p(m,null,{default:n(()=>[h(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RE%5B%22%E6%AD%A3%E5%88%99%E5%BC%8F%22%5D%20--%3E%20TH%5B%22Thompson%20NFA%22%5D%0A%20%20TH%20--%3E%20SUB%5B%22%E5%AD%90%E9%9B%86%E6%9E%84%E9%80%A0%22%5D%0A%20%20SUB%20--%3E%20DFA%5B%22%E8%AF%8D%E6%B3%95%20DFA%22%5D%0A%20%20DFA%20--%3E%20TOK%5B%22%E8%AE%B0%E5%8F%B7%E6%B5%81%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>正确性：对式子结构归纳，块认的语言等于子式。星号的绕回对应 Kleene 闭包。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>线性大小使生成器可处理人手写的标识符、数字正则。Unicode 字符类会把原子块打肥，不改变归纳。位置（行号）在 DFA 扫描时记，不在 Thompson 态上。</p><p>与<a href="/cs/kmp">KMP</a>：单模式精确串是正则的特例，KMP 不必走 NFA；词法是多记号正则并。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不匹配括号嵌套。不把最小化证完。后课默认：记号流由正则的 Thompson + DFA 产出。上下文无关文法接下一层嵌套，对象换成产生式，不再是有限自动机。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Thompson 按并、连、星拼 NFA，大小线性于式子。</li><li>再确定化得到词法 DFA；\\(\\varepsilon\\) 在闭包里消失。</li><li>嵌套结构不是正则，下一课 CFG。</li><li>出处：Thompson, 1968；Aho et al., 龙书第 3 章。</li></ul>',8))])}const v=r(d,[["render",c]]);export{F as __pageData,v as default};
